632→  function renderPreview(textarea, preview, label) {
633→    let raw = textarea.value;
634→    const anchors = [];
635→    let idx = 0;
636→    raw = raw.replace(/<a\s+href=("(?:[^"]*)"|'(?:[^']*)')\s*>([\s\S]*?)<\/a>/gi,
637→      (match, qHref, labelText) => {
638→        const href = qHref.slice(1, -1);
639→        const token = `__A_TAG_${idx++}__`;
640→        anchors.push({ token, href: normalizeHref(href), label: labelText });
641→        return token;
642→      });
643→    let safe = escapeHtml(raw);
644→    anchors.forEach(a => {
645→      const html = `<a href="${escapeHtml(a.href)}">${escapeHtml(a.label)}</a>`;
646→      safe = safe.replace(a.token, html);
647→    });
648→    safe = safe.replace(/\{PROBLEM=(.+?)\}/g, (_, p1) =>
649→      `<a href="/${escapeHtml(p1)}">[${escapeHtml(p1)}]</a>`
650→    );
651→    safe = safe.replace(/\n/g, "<br>");
652→    if (!safe.trim()) {
653→      preview.classList.add("hidden");
654→      label.classList.add("hidden");
655→      return;
656→    }
657→    preview.innerHTML = safe;
658→    preview.classList.remove("hidden");
659→    label.classList.remove("hidden");
660→    if (window.MathJax && MathJax.Hub) {
661→      MathJax.Hub.Queue(["Typeset", MathJax.Hub, preview]);
662→    }
663→  }
664→  document.querySelectorAll("form textarea").forEach(textarea => {
665→    const form = textarea.closest("form");
666→    const preview = form && form.querySelector(".post-preview");
667→    const label = form && form.querySelector(".preview-label");
668→    if (preview && label) {
669→      textarea.addEventListener("input", () => renderPreview(textarea, preview, label));
670→      renderPreview(textarea, preview, label);
671→    }
672→  });
673→});
674→</script>
