731→<!-- Redirect links and searches when in dual view mode -->
732→<script>
733→document.addEventListener("DOMContentLoaded", function () {
734→  if (!window.location.pathname.startsWith("/dual")) return;
735→
736→  function getTargetPanel() {
737→    const selected = document.querySelector('input[name="targetPanel"]:checked');
738→    return selected ? selected.value : "left";
739→  }
740→
741→  function loadInPanel(panel, path) {
742→    if (!path) return;
743→    const iframe = document.getElementById(`iframe-${panel}`);
744→    if (!iframe) return;
745→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
746→    iframe.src = url;
747→    const inputBox = document.querySelector(`#panel-${panel} input`);
748→    if (inputBox) inputBox.value = path;
749→    console.log(`Loaded "${url}" into panel "${panel}"`);
750→  }
751→  
752→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
753→    link.addEventListener("click", function (e) {
754→      e.preventDefault();
755→      const path = this.getAttribute("href");
756→      loadInPanel(getTargetPanel(), path);
757→    });
758→  });
759→
760→  const idForm = document.getElementById("idsearchForm");
