767→      let path = null;
768→
769→      if (/^\d+$/.test(input)) {
770→        path = "/go_to/" + encodeURIComponent(input);
771→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
772→        const parts = input.split(/\s+/).filter(Boolean);
773→        path = "/range/" + parts.map(encodeURIComponent).join("/");
774→      } else {
775→        alert("Invalid input format.");
776→        return;
777→      }
778→
779→      loadInPanel(getTargetPanel(), path);
780→    });
781→  }
782→
783→  const searchForm = document.getElementById("searchForm");
784→  if (searchForm) {
785→    searchForm.addEventListener("submit", function (e) {
786→      e.preventDefault();
787→      const input = searchForm.querySelector(".searchTerm").value.trim();
788→      if (!input) return;
789→
790→      const path = "/search/" + encodeURIComponent(input);
791→      loadInPanel(getTargetPanel(), path);
792→    });
793→  }
794→});
